  "stops": [{"at": {"line": 6, "hit": 2}, "ask": "Sau d\xF2ng n\xE0y tong b\u1EB1ng bao nhi\xEAu?", "expect": {"expr": "tong"}}],
  "narration": {"6": "C\u1ED9ng ch\u1EEF s\u1ED1 cu\u1ED1i v\xE0o t\u1ED5ng."},
